  color: var(--foreground);
  .aside-note {
    @apply my-4 p-4 border;
    background-color: var(--info-bg);
    color: var(--info-foreground);
    border-color: var(--info-border);
    border-inline-start-width: var(--spacing);
  }
  .aside-tip {
    @apply my-4 p-4 border;
    background-color: var(--success-bg);
    color: var(--success-foreground);
    border-color: var(--success-border);
    border-inline-start-width: var(--spacing);
  }
  .aside-caution {
    @apply my-4 p-4 border;
    background-color: var(--warning-bg);
    color: var(--warning-foreground);
    border-color: var(--warning-border);
    border-inline-start-width: var(--spacing);
  }
  .aside-danger {
    @apply my-4 p-4 border;
    background-color: var(--destructive-bg);
    color: var(--destructive-foreground);
    border-color: var(--destructive-border);
    border-inline-start-width: var(--spacing);
  }

  .leading-none {
    line-height: 1;
  }
}

.fullscreen #navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-100%);
  transition: transform 0.2s ease-in-out;
  z-index: var(--z-modal);
}

.fullscreen #navbar:hover,
.fullscreen #navbar:focus-within {
  transform: translateY(0);
}

.fullscreen #footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  transform: translateY(100%);
  transition: transform 0.2s ease-in-out;
  z-index: var(--z-modal);
}

.fullscreen #footer:hover,
.fullscreen #footer:focus-within {
  transform: translateY(0);
}

.fullscreen:has(#navbar:hover) #navbar,
.fullscreen:has(#footer:hover) #footer {
  transform: translateY(0);
}

@media (pointer: coarse) {
  .fullscreen #navbar,
  .fullscreen #footer {
    transition: none;
  }
}

